"""View audit records generated by real or test API requests."""
from database import connect, initialize

def main():
    initialize()
    with connect() as con:
        rows = con.execute('''SELECT id, timestamp_utc, request_id, http_status,
            outcome, COALESCE(predicted_class, '-'), COALESCE(error_type, '-')
            FROM prediction_audit ORDER BY id DESC LIMIT 20''').fetchall()
        print('ID | UTC Time | Request ID | HTTP | Outcome | Prediction | Error')
        for row in rows:
            print(' | '.join(map(str, row)))
        success, failed = con.execute('''SELECT
            SUM(CASE WHEN outcome='success' THEN 1 ELSE 0 END),
            SUM(CASE WHEN outcome='failed' THEN 1 ELSE 0 END)
            FROM prediction_audit''').fetchone()
        print(f'\nTotal: success={success or 0}; failed={failed or 0}')

if __name__ == '__main__':
    main()
